INSERT INTO public.answer_trap_questions (id,question_stem,options,correct_answer,trap_type,trap_display_name,key_cue,why_correct_short,why_wrong_short,one_line_fix,difficulty,nclex_category) VALUES
('3a34000b-33aa-5bbd-8681-67efe85ab23d','The RN has an established ambulation plan for a stable post-operative client and delegates the walk to a competent UAP. What must the RN do after delegating?','[{"label": "A", "text": "Nothing further; the UAP is now responsible for the task"}, {"label": "B", "text": "Document that the UAP completed the ambulation"}, {"label": "C", "text": "Have the UAP evaluate the client''s pain and decide whether to continue the walks"}, {"label": "D", "text": "Follow up with the UAP and the client to verify the walk was completed and tolerated"}]','D','Delegation','Delegation','The RN delegated an established walk for a stable client.','The five rights of delegation include right supervision and evaluation. The RN follows up with both the delegatee and the client to confirm the task was completed correctly and to evaluate the client''s response.','The RN remains accountable for the delegation decision and supervision; the UAP remains accountable for their own performance and reporting. Accountability is not transferred away from the RN.','Delegation includes follow-up and RN evaluation of the client''s response.','2','Management of Care'),
('d9c30d7e-9859-5f6d-84f6-ac9b4281d198','A stable client has an established wound-care plan that includes a sterile dressing change. In this setting, sterile dressing changes are authorized for the competent LPN but not the UAP. Which assignment is appropriate?','[{"label": "A", "text": "Assign it to the LPN, if competent in sterile technique per facility policy"}, {"label": "B", "text": "Assign it to the UAP, since dressing changes are routine"}, {"label": "C", "text": "Assign it to the UAP as long as the RN supervises directly"}, {"label": "D", "text": "Ask a family member to do it, since they will manage wound care at home anyway"}]','A','Delegation','Delegation','The setting authorizes the dressing change for a competent LPN, not the UAP.','The task matches the LPN''s authorized scope, competence, and the setting''s policy for a stable client with an established plan. Whether a task can be delegated depends on the client''s condition, staff competence, applicable scope, instructions, and supervision — not on the task''s name alone.','In this setting the task is not authorized for the UAP. Delegability depends on scope and policy, not on whether the task seems routine.','Both role authorization and procedure-specific competence are needed.','2','Management of Care'),
('59ee80b5-120b-5bf1-97cc-578f29a14335','An adult has been instructed to take a levothyroxine sodium tablet at 6 a.m., 30–60 minutes before breakfast. Which calcium-supplement schedule follows the labeled separation instruction?','[{"label": "A", "text": "Take calcium at 10 a.m. or later."}, {"label": "B", "text": "Take calcium with levothyroxine at 6 a.m."}, {"label": "C", "text": "Take calcium with breakfast at 7 a.m."}, {"label": "D", "text": "Take calcium at 8 a.m."}]','A','Medication reasoning','Medication reasoning','Levothyroxine is scheduled at 6 a.m.','Calcium can reduce levothyroxine absorption. The cited tablet label instructs separation by at least four hours; 10 a.m. is four hours after 6 a.m.','The medicines would be taken together.','Separate the specified levothyroxine tablet and calcium by at least four hours.','2','Pharmacological Therapies'),
('d02faee7-4dcf-569b-8a66-0047700a3718','An adult reports difficulty swallowing the prescribed metformin hydrochloride extended-release tablet. Its labeling says to swallow it whole without cutting, crushing, or chewing. What should the nurse advise?','[{"label": "A", "text": "Crush it into a small amount of applesauce."}, {"label": "B", "text": "Cut it into quarters and swallow each piece."}, {"label": "C", "text": "Chew it thoroughly with the evening meal."}, {"label": "D", "text": "Contact the pharmacist or prescriber for a suitable alternative formulation or plan rather than modifying the tablet."}]','D','Medication reasoning','Medication reasoning','This product''s label explicitly prohibits modification.','The patient''s swallowing concern needs a workable medication plan that respects the product''s formulation instructions.','Crushing contradicts this product''s label.','Do not cut, crush, or chew the specified metformin ER tablet; seek a suitable alternative.','2','Pharmacological Therapies'),
('d7be5455-a7ac-51b6-9084-ac4705d9251f','Two hospitalized clients have prescriptions for the same insulin pen product and concentration. One client''s pen is available. Which action is appropriate?','[{"label": "A", "text": "Use that pen for both clients if a new needle is attached each time."}, {"label": "B", "text": "Use it for the second client after disinfecting its exterior."}, {"label": "C", "text": "Use it for both if their prescribed doses are identical."}, {"label": "D", "text": "Obtain the second client''s own pen; never share a pen between patients."}]','D','Medication reasoning','Medication reasoning','The question concerns sharing an insulin pen.','Insulin pens are for one patient only. Changing the needle does not eliminate the bloodborne-pathogen risk from sharing the device.','A fresh needle does not make the pen shareable.','An insulin pen is for one patient, even when a new needle is used.','2','Safety and Infection Control'),
('da9b69ad-747d-54f0-a625-3ab928b4c8ac','When removing a surgical mask after client care, which technique prevents self-contamination?','[{"label": "A", "text": "Grasp the front of the mask and pull it forward"}, {"label": "B", "text": "Let the mask hang around the neck for reuse later"}, {"label": "C", "text": "Fold the mask front-to-front and place it in a pocket"}, {"label": "D", "text": "Handle only the ties or ear loops, avoiding the front of the mask"}]','D','Safety','Safety','The nurse is removing a used surgical mask.','The front of the mask is contaminated from droplets. Handling only the ties or ear loops keeps the nurse''s hands on the clean parts and avoids transferring pathogens to the hands or face.','The front of the mask is the contaminated surface; grasping it transfers pathogens directly to the hands.','Remove a used surgical mask by its ties or loops without touching the front.','2','Safety and Infection Control'),
('faff07ef-3854-5c5d-a9e6-b93a71373222','A hospitalized client is being evaluated for infectious pulmonary tuberculosis. An airborne infection isolation room is available. Which placement and entry plan is appropriate?','[{"label": "A", "text": "Use a private room with droplet precautions and a surgical mask for staff entry."}, {"label": "B", "text": "Use the isolation room and the required fit-tested N95 or higher respirator for staff entry."}, {"label": "C", "text": "Use a shared room after giving the client a surgical mask."}, {"label": "D", "text": "Use contact precautions without respiratory protection."}]','B','Safety','Safety','Infectious pulmonary TB is suspected, so airborne precautions are indicated.','Airborne placement and appropriate respiratory protection address inhalation exposure while evaluation proceeds.','Droplet-only protection is insufficient for suspected infectious pulmonary TB when airborne controls are available.','For infectious pulmonary TB, use airborne controls; a patient mask does not replace a fit-tested respirator for staff entering the room.','2','Safety and Infection Control'),
('01e8b36a-ce69-5434-a071-45a5289382c7','Facility protocol requires sterile gloves and aseptic handling of central-line dressing supplies. After donning sterile gloves, the RN touches the bed rail with one glove before touching the prepared site. What should the RN do?','[{"label": "A", "text": "Wipe the glove on a clean towel and continue."}, {"label": "B", "text": "Stop and replace the contaminated gloves using hand hygiene and the facility\u2019s aseptic sequence before continuing."}, {"label": "C", "text": "Use the contaminated glove only to press the new dressing over the insertion site."}, {"label": "D", "text": "Continue because the bed rail is part of the client\u2019s immediate environment."}]','B','Safety','Safety','The glove touched a nonsterile surface before sterile-site care.','The contamination must be corrected before site or dressing contact.','A towel wipe does not restore sterility.','Maintain asepsis during central-line dressing care; correct contamination before contact with the prepared site or new dressing.','2','Reduction of Risk Potential'),
('ca33e716-cd3f-5c2f-b3c9-61cf31ff5f96','A client taking lithium says, "I will sharply cut out salt this week to make my diet healthier." No diet change has been prescribed. Which response is best?','[{"label": "A", "text": "Make the diet change now and keep the next routine visit."}, {"label": "B", "text": "Discuss the change with the prescriber and follow the agreed salt and fluid plan."}, {"label": "C", "text": "Skip lithium on days when the meals contain less salt."}, {"label": "D", "text": "Add a large daily salt supplement before cutting food sources of salt."}]','B','Medication reasoning','Medication reasoning','A sudden sodium change can affect lithium handling.','Lithium treatment requires attention to salt and fluid intake; an abrupt low-salt change should not be made independently.','Routine follow-up alone does not address the effect of an abrupt change.','Follow the prescribed salt and fluid plan while taking lithium; abrupt low-salt diets or dehydration need clinician guidance.','2','Pharmacological Therapies'),
('46d7efa7-96f7-59cb-ae33-0e52196d8868','An adult with several days of diarrhea has potassium 2.7 mEq/L. The monitor shows flattened T waves and prominent U waves. Which interpretation best fits these findings?','[{"label": "A", "text": "The laboratory result indicates hyperkalemia because U waves reflect excess potassium."}, {"label": "B", "text": "The tracing indicates hyperkalemia, because flattened T waves reflect potassium excess."}, {"label": "C", "text": "The client has hypokalemia, but prominent U waves show the potassium is returning to normal."}, {"label": "D", "text": "The laboratory result indicates hypokalemia, and the described ECG changes are compatible with it."}]','D','Assessment-first','Assessment-first','Low measured potassium with a prominent post-T deflection.','Both the low laboratory result and described repolarization changes fit potassium depletion.','2.7 mEq/L is low potassium; prominent U waves are compatible with depletion.','Distinguish potassium patterns using laboratory context: flattened T/prominent U waves support low potassium; tall peaked T waves can accompany high potassium. ECG does not replace laboratory assessment.','2','Physiological Adaptation'),
('de2ac7c4-52f8-597d-9b0f-5a5e404ca2b5','Where should an indwelling urinary catheter''s drainage bag be positioned?','[{"label": "A", "text": "Above the bladder"}, {"label": "B", "text": "On the floor"}, {"label": "C", "text": "Below bladder level and off the floor"}, {"label": "D", "text": "With the tube tightly kinked"}]','C','Patient education','Patient education','The question concerns drainage-bag position.','Dependent unobstructed drainage is recommended.','This risks backflow.','Keep catheter drainage dependent and unobstructed, with the bag off the floor.','2','Basic Care and Comfort'),
('ae5df3fc-98e4-5217-ab8d-f5047b69ca4a','A stable adult is receiving continuous gastric tube feeding. Tube placement has been checked per policy, and there is no contraindication to head elevation. Which position supports aspiration-risk reduction?','[{"label": "A", "text": "Keep the head of the bed elevated about 30\u201345 degrees."}, {"label": "B", "text": "Keep the bed flat because the feeding is entering a tube."}, {"label": "C", "text": "Lower the head below the feet to help formula move forward."}, {"label": "D", "text": "Elevate the knees while leaving the head of the bed flat."}]','A','Safety','Safety','A safe feeding setup includes positioning as well as placement checks.','Recommended elevation helps reduce aspiration risk during feeding; continue other prescribed checks and monitoring.','A gastric tube does not remove aspiration risk when the client is supine.','During gastric tube feeding, maintain prescribed head-of-bed elevation, commonly 30–45 degrees unless contraindicated, alongside the other feeding safety checks.','2','Basic Care and Comfort')
